import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    label = int(ctx.index) % 3
    return {"inputs": synth.Tensor(features), "labels": synth.Tensor(torch.tensor(float(label)))}
dataset = synth.Spec("proxy-anchor-embeddings", generator=samples, size=12, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class EmbeddingModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=3)
        self.proxies = nn.Parameter(torch.randn(3, 3))
    def forward(self, inputs):
        return {"embeddings": self.network(inputs), "proxies": self.proxies}
trainer = Trainer(EmbeddingModel(), train, recipe="structured-objective", recipe_config={"loss": "proxy-anchor", "loss_kwargs": {"alpha": 32.0, "delta": 0.1}, "bindings": {"logits_or_prediction": {"output": "embeddings"}, "targets": {"batch": "labels"}, "proxies": {"output": "proxies"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
